import urllib.request
from html.parser import HTMLParser
class Text(HTMLParser):
 def handle_data(self, data):
  if data.strip(): print(data.strip())
for url in ['https://developers.openai.com/api/reference/resources/responses/methods/create','https://developers.openai.com/api/docs/guides/your-data']:
 print('SOURCE:', url)
 try:
  raw=urllib.request.urlopen(url,timeout=25).read().decode()
  p=Text()
  import contextlib,io
  out=io.StringIO()
  with contextlib.redirect_stdout(out): p.feed(raw)
  lines=out.getvalue().splitlines()
  for i,line in enumerate(lines):
   if any(s in line.lower() for s in ['store','output_text','abuse monitoring','30 days','authorization','/v1/responses']):
    print(' | '.join(lines[max(0,i-1):i+4])[:1100])
 except Exception as e: print(type(e).__name__, str(e))
PY"

